-- Carga de la consulta a RENAPER — ciudadanos_renaper.csv
-- Generado el 2026-09-18 · 10321 filas · MariaDB / MySQL (utf8mb4)
--
-- El archivo es la respuesta cruda de RENAPER para un lote de DNI. Las columnas
-- `*_origen` son lo que se envio a consultar; el resto es lo que devolvio la API.
-- Las 101 filas con `_ok` = 0 no trajeron datos: ahi todo lo de la API es NULL.

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `ciudadanos_renaper`;

CREATE TABLE `ciudadanos_renaper` (
  -- Lo consultado
  `dni_consultado`        VARCHAR(20)      NOT NULL COMMENT 'DNI enviado a consultar; clave del lote',
  `apellido_origen`       VARCHAR(60)      NOT NULL COMMENT 'Apellido del padron de origen',
  `nombre_origen`         VARCHAR(60)      NOT NULL COMMENT 'Nombre del padron de origen',
  `sexo_origen`           VARCHAR(10)          NULL COMMENT 'Femenino / Masculino',
  -- Lo que devolvio RENAPER
  `cuil`                  VARCHAR(11)          NULL,
  `dni`                   VARCHAR(20)          NULL COMMENT 'DNI segun RENAPER; puede diferir del consultado',
  `apellido`              VARCHAR(60)          NULL,
  `nombre`                VARCHAR(60)          NULL,
  `genero`                CHAR(1)              NULL COMMENT 'F / M',
  `sexo`                  TINYINT UNSIGNED     NULL COMMENT '1 = F, 2 = M',
  `tipo_documento`        VARCHAR(10)          NULL,
  `fecha_nacimiento`      DATE                 NULL,
  -- Domicilio
  `provincia_api`         VARCHAR(40)          NULL,
  `municipio_api`         VARCHAR(60)          NULL,
  `localidad_api`         VARCHAR(60)          NULL,
  `codigo_postal`         VARCHAR(10)          NULL,
  `calle`                 VARCHAR(120)         NULL,
  `altura`                VARCHAR(10)          NULL,
  `piso_vivienda`         VARCHAR(10)          NULL COMMENT 'Se guarda como texto: hay valores 00',
  `departamento_vivienda` VARCHAR(10)          NULL COMMENT 'Se guarda como texto: hay valores 00',
  `barrio`                VARCHAR(60)          NULL,
  `monoblock`             VARCHAR(60)          NULL,
  `nacionalidad_api`      VARCHAR(40)          NULL,
  -- Resultado de la llamada
  `_ok`                   TINYINT(1)       NOT NULL DEFAULT 0 COMMENT '1 = la API devolvio la persona',
  `_error`                VARCHAR(255)         NULL,
  `_http_status`          SMALLINT UNSIGNED    NULL,
  PRIMARY KEY (`dni_consultado`),
  KEY `idx_renaper_dni` (`dni`),
  KEY `idx_renaper_cuil` (`cuil`),
  KEY `idx_renaper_apellido_nombre` (`apellido`, `nombre`),
  KEY `idx_renaper_ok` (`_ok`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






















